/**
 * Converts a JSON string to a JavaScript object
 * @param jsonString The JSON string to convert
 * @returns The parsed object or null if parsing fails
 */
function convertJsonToObject<T>(jsonString: string): T | null {
  try {
    // Parse the JSON string into a JavaScript object
    const data = JSON.parse(jsonString) as T;
    return data;
  } catch (error) {
    console.error('Error parsing JSON:', error);
    return null;
  }
}

export async function getNextData<T>(path: string, jsonString?: object): Promise<any> {
  // Use provided JSON string or fallback to bigData
  //const parsedData = jsonString ? convertJsonToObject<any>(jsonString) : convertJsonToObject<any>(bigData);
  const parsedData = jsonString ? jsonString : nextData as object;
  //console.log("-------big--data--->>", parsedData);
  
  if (!parsedData) {
    return null;
  }
  
  // Handle accessing nested properties
  try {
    const pathParts = path.split('.');
    let result = parsedData as Record<string, any>;
    
    for (const part of pathParts) {
      if (result && typeof result === 'object') {
        result = result[part];
      } else {
        return null;
      }
      
      if (result === undefined) {
        return null;
      }
    }
    

    return Object.entries(result).map(([id, track]) => ({
      id,
      ...track,
    }));
    
   // return result;
  } catch (error) {
    console.error('Error accessing nested property:', error);
    return null;
  }
}